2.2 Map of Sites
Here are the sites from dmr_rasher_steneck


Show the code
# make sf obj
kelptime_study &lt;- kelptime_study |&gt; st_as_sf(
  coords = c("longitude", "latitude"),
  crs = 4326
)

# colors!
good_cols &lt;- colors() |&gt; 
  stringr::str_subset("gr[ea]y", negate = TRUE) |&gt;
  stringr::str_subset("white", negate = TRUE) |&gt;
  stringr::str_subset("black", negate = TRUE) |&gt;
  gplots::col2hex()

# get site-level LL
kelptime_study_grouped &lt;- kelptime_study |&gt;
  group_by(trajectory) |&gt;
  summarize(study = study[1],
            site = site[1],
            min_year = min(sample_year),
            max_year = max(sample_year),
            n = n(),
            eco_collapsed = eco_collapsed[1]) |&gt;
  mutate(text = glue("{trajectory}&lt;br&gt;study: {study}&lt;br&gt;{min_year} - {max_year}, n = {n}&lt;br&gt;site: {site}&lt;br&gt;{eco_collapsed}"),
         col = good_cols[rank(trajectory) |&gt; round()])

leaflet() |&gt;
  addTiles() |&gt;
  addCircleMarkers(data = kelptime_study_grouped |&gt; st_centroid(),
             fillColor = ~col,
             fillOpacity = 0.8,
             popup = ~text,
             stroke = 0)

